void bn_set_2b(bn_t a, int b) {
        int i, d;

        if (b < 0) {
                bn_zero(a);
        } else {
                RLC_RIP(b, d, b);

                bn_grow(a, d + 1);
                for (i = 0; i < d; i++) {
                        a->dp[i] = 0;
                }
                a->used = d + 1;
                a->dp[d] = ((dig_t)1 << b);
                a->sign = RLC_POS;
        }
}

void bn_rand(bn_t a, int sign, int bits) {
        int digits;

        RLC_RIP(bits, digits, bits);
        digits += (bits > 0 ? 1 : 0);

        bn_grow(a, digits);

        rand_bytes((uint8_t *)a->dp, digits * sizeof(dig_t));

        a->used = digits;
        a->sign = sign;
        if (bits > 0) {
                dig_t mask = ((dig_t)1 << (dig_t)bits) - 1;
                a->dp[a->used - 1] &= mask;
        }
        bn_trim(a);
}
